1	package mevwatch
2	
3	// Regression coverage for `rules show` (GetVersion) against a registered
4	// version whose stored archive document has decayed since registration.
5	// Showing a version must prove its actual stored declaration still
6	// satisfies the registration rules — the same proof registration,
7	// enabling, comparison, evaluation and replay already demand — so a
8	// corrupt registered version is refused with ErrCorruptVersion (never
9	// shown with silently zeroed or defaulted parameters, never substituted
10	// with the enabled, built-in or default parameters, never reported
11	// unknown), even when it is the currently enabled version. The check
12	// covers only the requested version: a corrupt sibling never blocks
13	// showing an intact one, and the query never rewrites the archive.
14	
15	import (
16		"errors"
17		"os"
18		"path/filepath"
19		"reflect"
20		"strings"
21		"testing"
22	)
23	
24	// TestShowCorruptVersionRefused runs the full corruption matrix against
25	// showing a registered version: every way its stored document can stop
26	// satisfying the registration rules must fail with ErrCorruptVersion, name
27	// the version and the offending rule or field, and leave the archive
28	// untouched.
29	func TestShowCorruptVersionRefused(t *testing.T) {
30		for _, tc := range corruptVersionCases {
31			t.Run(tc.name, func(t *testing.T) {
32				dir := setupCorruptCompareArchive(t)
33				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
34					tc.mutate(t, ver)
35				})
36				before := readArchiveFile(t, dir)
37	
38				v, err := GetVersion(dir, "candC")
39				if err == nil {
40					t.Fatalf("corrupt version shown successfully: %+v", v)
41				}
42				if !errors.Is(err, ErrCorruptVersion) {
43					t.Fatalf("error = %v, want ErrCorruptVersion", err)
44				}
45				if errors.Is(err, ErrUnknownVersion) {
46					t.Fatalf("registered-but-corrupt version misreported as unknown: %v", err)
47				}
48				if !strings.Contains(err.Error(), "candC") {
49					t.Fatalf("error must name the requested version, got %v", err)
50				}
51				if !strings.Contains(err.Error(), tc.wantErr) {
52					t.Fatalf("error must name the offending rule or field %q, got %v", tc.wantErr, err)
53				}
54				if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
55					t.Fatalf("refused show changed the archive:\nbefore=%s\nafter =%s", before, after)
56				}
57			})
58		}
59	}
60	
61	// TestShowCorruptEnabledVersionRefused pins the core regression: the
62	// integrity check runs even when the requested id is the currently enabled
63	// version, and a corrupt enabled version blocks neither showing an intact
64	// sibling nor showing builtin.
65	func TestShowCorruptEnabledVersionRefused(t *testing.T) {
66		for _, tc := range corruptVersionCases {
67			t.Run(tc.name, func(t *testing.T) {
68				dir := setupCorruptCompareArchive(t)
69				if _, err := EnableVersion(dir, "candC"); err != nil {
70					t.Fatalf("setup: EnableVersion candC: %v", err)
71				}
72				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
73					tc.mutate(t, ver)
74				})
75				before := readArchiveFile(t, dir)
76	
77				v, err := GetVersion(dir, "candC")
78				if !errors.Is(err, ErrCorruptVersion) {
79					t.Fatalf("showing the corrupt enabled version: v=%+v err=%v, want ErrCorruptVersion", v, err)
80				}
81				if errors.Is(err, ErrUnknownVersion) {
82					t.Fatalf("corrupt enabled version misreported as unknown: %v", err)
83				}
